"""Authored 16px diagnostic paper certificates. No final boss loot or economic value."""
import json
from pathlib import Path
from PIL import Image,ImageDraw
R=Path(__file__).resolve().parents[1]/"src/main/resources/assets/slavicmyths"
def write(p,d):
 p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
for name in ("posad_test_proof","posad_test_receipt"):
 im=Image.new("RGBA",(16,16));d=ImageDraw.Draw(im)
 if name.endswith("proof"):
  d.rectangle((3,1,11,13),fill="#554536");d.rectangle((4,2,10,12),fill="#e7d9ac");d.rectangle((2,1,12,2),fill="#b39868");d.rectangle((2,12,12,13),fill="#b39868")
  for y in (4,6,8):d.line((5,y,9,y),fill="#8d8062")
  d.rectangle((9,9,13,13),fill="#6c2425");d.rectangle((10,10,12,12),fill="#c94b45");d.point((11,11),fill="#ffe2a6")
 else:
  d.polygon(((1,4),(11,4),(14,7),(14,12),(1,12)),fill="#554536");d.polygon(((2,5),(10,5),(13,8),(13,11),(2,11)),fill="#e7d9ac");d.polygon(((10,5),(10,8),(13,8)),fill="#b39868")
  d.line(((4,8),(6,10),(10,6)),fill="#285b4c",width=2)
 path=R/"textures/item"/(name+".png");path.parent.mkdir(parents=True,exist_ok=True);im.save(path)
 write(R/"models/item"/(name+".json"),{"parent":"minecraft:item/generated","textures":{"layer0":"slavicmyths:item/"+name}})
ru={"item.slavicmyths.posad_test_proof":"Тестовое подтверждение победы","item.slavicmyths.posad_test_receipt":"Тестовая отметка обмена","posad.test.proof.named":"Тестовое подтверждение: %s","posad.test.receipt.named":"Тестовый обмен: %s","posad.test.only":"Проверка механик. Окончательные награды не утверждены.","posad.test.invalid":"У этого подтверждения нет подлинной серверной записи.","posad.test.redeemed":"Это подтверждение уже погашено. Повторной выдачи нет.","posad.test.exchanged":"Тестовый обмен учтён. Выдана проверочная отметка, без окончательной награды.","posad.test.kind.mytar":"Проклятый мытарь","posad.test.kind.bauk":"Баук","posad.test.kind.raven":"Моровой ворон","posad.test.kind.zmey":"Моровой змей","posad.test.kind.fever_sisters":"Гнетея и Трясея","posad.test.kind.element_sisters":"Огнея и Лидея"}
en={"item.slavicmyths.posad_test_proof":"Test victory certificate","item.slavicmyths.posad_test_receipt":"Test exchange receipt","posad.test.proof.named":"Test victory: %s","posad.test.receipt.named":"Test exchange: %s","posad.test.only":"Mechanics test. Final rewards are not approved.","posad.test.invalid":"No authentic server record exists for this certificate.","posad.test.redeemed":"This certificate was already redeemed. No repeat reward.","posad.test.exchanged":"Test exchange recorded. A diagnostic receipt replaces the unapproved final reward.","posad.test.kind.mytar":"Cursed Mytar","posad.test.kind.bauk":"Bauk","posad.test.kind.raven":"Morovoy Raven","posad.test.kind.zmey":"Morovoy Fire Zmey","posad.test.kind.fever_sisters":"Gneteya and Tryaseya","posad.test.kind.element_sisters":"Ogneya and Ledeya"}
ru.update({"posad.test.near_leader":"Обратитесь к посаднику рядом с вами.","posad.test.nether":"Следы адских боссов доступны у посадника в Незере.","posad.test.no_trace":"Нет подтверждённого следа: %s. Поиск не создаёт босса и не загружает новые чанки.","posad.test.trace":"%s: последнее известное место — Незер, X=%s Z=%s, область поиска %s блоков. %s","posad.test.trace.loaded":"Босс сейчас находится в загруженной области.","posad.test.trace.unloaded":"Сохранён реальный след; область сейчас не загружена.","posad.test.dialogue":"Посадник: поиск известных боссов (нажмите имя). Окончательные поручения и награды отложены.","posad.test.exchange_hint":"Предъявите подлинное тестовое подтверждение в основной руке: проверочный обмен без окончательных наград.","posad.test.encounter.missing":"Не зарегистрирован босс: %s","posad.test.encounter.rejected":"Создание тестовой встречи отклонено. Добавленные этим вызовом сущности удалены.","posad.test.encounter.created":"Создана тестовая встреча: %s, X=%s Y=%s Z=%s. Это OP-проверка механик, не правило естественного появления.","posad.test.encounter.no_space":"Нет безопасного загруженного места рядом. Нужны свободное пространство и природное основание вне построек; блоки не менялись.","posad.test.encounter.cleared":"Удалено тестовых боссов в загруженной области радиусом 64 блока: %s"})
en.update({"posad.test.near_leader":"Speak to a nearby Posadnik.","posad.test.nether":"Nether boss traces are available from a Posadnik in the Nether.","posad.test.no_trace":"No confirmed trace: %s. Search does not spawn bosses or load new chunks.","posad.test.trace":"%s: last observed in the Nether at X=%s Z=%s, search area %s blocks. %s","posad.test.trace.loaded":"The boss is currently in loaded terrain.","posad.test.trace.unloaded":"This is a saved real trace; its area is unloaded.","posad.test.dialogue":"Posadnik: known boss traces (click a name). Final quests and rewards are deferred.","posad.test.exchange_hint":"Present an authentic test certificate in your main hand for a diagnostic exchange without final rewards.","posad.test.encounter.missing":"Unregistered boss: %s","posad.test.encounter.rejected":"Test encounter creation rejected. Entities inserted by this attempt were removed.","posad.test.encounter.created":"Test encounter created: %s, X=%s Y=%s Z=%s. This is an OP mechanics fixture, not a natural spawn rule.","posad.test.encounter.no_space":"No safe loaded site nearby. Find clear space and natural footing outside structures; no blocks were changed.","posad.test.encounter.cleared":"Removed loaded diagnostic bosses within 64 blocks: %s"})
for lang,labels in (("ru_ru",ru),("en_us",en)):
 p=R/"lang"/(lang+".json");d=json.loads(p.read_text(encoding="utf-8"));d.update(labels);write(p,d)
p=R/"creative_catalog.tsv";s=p.read_text(encoding="utf-8").rstrip()+"\n"
for name in ("posad_test_proof","posad_test_receipt"):
 if name+"\t" not in s:s+=name+"\tresources\tboss_material\n"
p.write_text(s,encoding="utf-8")
